values:node:5	O:23:"Drupal\\\\node\\\\Entity\\\\Node":27:{s:10:"in_preview";N;s:9:"\\000*\\000values";a:20:{s:3:"vid";a:1:{s:9:"x-default";s:1:"5";}s:8:"langcode";a:1:{s:9:"x-default";s:2:"en";}s:12:"revision_uid";a:1:{s:9:"x-default";s:1:"1";}s:18:"revision_timestamp";a:1:{s:9:"x-default";s:10:"1451998331";}s:12:"revision_log";a:1:{s:9:"x-default";N;}s:16:"revision_default";a:1:{s:9:"x-default";s:1:"1";}s:3:"nid";a:1:{s:9:"x-default";s:1:"5";}s:4:"type";a:1:{s:9:"x-default";s:4:"page";}s:4:"uuid";a:1:{s:9:"x-default";s:36:"4b881874-7f9e-4b44-bb05-0530941b7390";}s:17:"isDefaultRevision";a:1:{s:9:"x-default";s:1:"1";}s:6:"status";a:1:{s:9:"x-default";s:1:"1";}s:5:"title";a:1:{s:9:"x-default";s:22:"About More than Themes";}s:3:"uid";a:1:{s:9:"x-default";s:1:"1";}s:7:"created";a:1:{s:9:"x-default";s:10:"1451998315";}s:7:"changed";a:1:{s:9:"x-default";s:10:"1451999340";}s:7:"promote";a:1:{s:9:"x-default";s:1:"0";}s:6:"sticky";a:1:{s:9:"x-default";s:1:"0";}s:16:"default_langcode";a:1:{s:9:"x-default";s:1:"1";}s:29:"revision_translation_affected";a:1:{s:9:"x-default";s:1:"1";}s:4:"body";a:1:{s:9:"x-default";a:1:{i:0;a:3:{s:5:"value";s:1958:"<h3>Introduction</h3>\\015\\012\\015\\012<p><a href="http://www.morethanthemes.com/&amp;mt-referral=scholarlylite" target="_blank">More than (just) Themes</a>&nbsp;proudly presents some of the best Drupal, HTML &amp; PSD themes &amp; toolsets around. Some&nbsp;<a href="http://www.drupalizing.com/" target="_blank">awesome freebies</a>&nbsp;too. With pixel-perfect design, automated installation procedure, unique support and detailed installation instructions, all created by people you can easily reach, people like you; bloggers, web designers, coders and Drupal geeks.</p>\\015\\012\\015\\012<h3>About News+ Lite and Our Mission</h3>\\015\\012\\015\\012<p>News+ Lite is a free, news/portal theme for Drupal 8 built on Bootstrap 3 and our popular <a href="http://www.morethanthemes.com/?q=themes/newsplus">News+ Premium theme for Drupal 7</a>.</p>\\015\\012\\015\\012<blockquote>\\015\\012<p>News+ Lite has been contributed to Drupal and is supported by&nbsp;<a href="http://www.morethanthemes.com/&amp;mt-referral=scholarlylite" target="_blank">More than (just) Themes</a>, as part of our ongoing effort to bring top quality themes to the Drupal community.&nbsp;</p>\\015\\012</blockquote>\\015\\012\\015\\012<p>You can use News+ Lite without any limitations for your personal or commercial projects. Although attribution is very much appreciated, it is not required.</p>\\015\\012\\015\\012<h4>Support &amp; Contact us</h4>\\015\\012\\015\\012<p>In addition to our Premium Drupal products, at More than (just) Themes we will continue to release, maintain, improve and enrich our free themes with new features.&nbsp;</p>\\015\\012\\015\\012<p>Members of our team participate actively and help out in support requests to the maximum extent possible. Nevertheless, sometimes there might be needs related to a theme that go beyond the typical support and knowledge sharing and require either premium support or even implementation-on-request. In all such cases, do not hesitate to <a href="http://www.morethanthemes.com/&amp;mt-referral=scholarlylite" target="_blank">get in touch with us</a> :)</p>\\015\\012";s:7:"summary";s:0:"";s:6:"format";s:9:"full_html";}}}}s:9:"\\000*\\000fields";a:0:{}s:19:"\\000*\\000fieldDefinitions";N;s:12:"\\000*\\000languages";N;s:14:"\\000*\\000langcodeKey";s:8:"langcode";s:21:"\\000*\\000defaultLangcodeKey";s:16:"default_langcode";s:17:"\\000*\\000activeLangcode";s:9:"x-default";s:18:"\\000*\\000defaultLangcode";s:2:"en";s:15:"\\000*\\000translations";a:1:{s:9:"x-default";a:1:{s:6:"status";i:1;}}s:24:"\\000*\\000translationInitialize";b:0;s:14:"\\000*\\000newRevision";b:0;s:20:"\\000*\\000isDefaultRevision";s:1:"1";s:13:"\\000*\\000entityKeys";a:4:{s:6:"bundle";s:4:"page";s:2:"id";s:1:"5";s:8:"revision";s:1:"5";s:4:"uuid";s:36:"4b881874-7f9e-4b44-bb05-0530941b7390";}s:25:"\\000*\\000translatableEntit