entity_view:block:witharichfooter:[languages:language_interface]=en:[theme]=newsplus_lite:[user.permissions]=6dcdff94e8f1f2b622903c3be3c4d8a33ca75fd2483416d0eb7121e4a57bbc1b	a:3:{s:7:"#markup";O:25:"Drupal\\\\Core\\\\Render\\\\Markup":1:{s:9:"\\000*\\000string";s:689:"<div id="block-witharichfooter" class="block block-block-content block-block-content1047b0e5-cfbe-4e2a-a400-dd4b71604b8c">\\012  \\012    \\012      <div class="content">\\012      \\012            <div class="clearfix text-formatted field field--name-body field--type-text-with-summary field--label-hidden field__item"><h3>WITH A RICH FOOTER</h3>\\012\\012<p>News+ Lite comes with a wealth of regions and classes, providing, among others, a rich multi-level footer where you can place lots of information about your site.</p>\\012\\012<p>Therefore, the important pages of your site, can always be just one click away for your visitor, regardless where in your site they are navigating.</p>\\012</div>\\012      \\012    </div>\\012  </div>\\012";}s:9:"#attached";a:0:{}s:6:"#cache";a:3:{s:8:"contexts";a:3:{i:0;s:28:"languages:language_interface";i:1;s:5:"theme";i:2;s:16:"user.permissions";}s:4:"tags";a:5:{i:0;s:15:"block_content:7";i:1;s:18:"block_content_view";i:2;s:10:"block_view";i:3;s:34:"config:block.block.witharichfooter";i:4;s:30:"config:filter.format.full_html";}s:7:"max-age";i:-1;}}	-1	1530559437.406	1	block_content:7 block_content_view block_view config:block.block.witharichfooter config:filter.format.full_html rendered	0
